import {allMemories,putMemories,removeMemory,filterMemories,validateFiles,cleanMemory,readSettings,writeSettings,CATEGORIES} from './store.js';
import {MemoryGarden,FallbackGarden} from './vr.js';
const $=s=>document.querySelector(s), app=$('#app'),dialog=$('#detail');
const paths={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',memories:'M4 5h16v15H4Z M7 2v6 M17 2v6 M4 10h16',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',experience:'M3 8h18v10h-6l-3-3-3 3H3Z M6 12h3 M15 12h3',profile:'M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 22v-3a8 8 0 0 1 16 0v3',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',heart:'M12 21 3 12C-3 3 7-1 12 6 17-1 27 3 21 12Z',sound:'M3 9h4l5-5v16l-5-5H3Z M16 7q7 5 0 10'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.memories}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const demos=[{id:'demo-1',title:'Sunday, slow and golden',category:'Family',date:'2024-06-16',story:'The sunlight found its way into every corner. We made tea and stayed a little longer.\n\nThis is an illustrative sample story, ready to be replaced with your own.',position:'80% 50%'},{id:'demo-2',title:'The place we called home',category:'Friend',date:'2023-09-02',story:'A familiar room, a favourite chair, and the comfort of having nowhere else to be.\n\nIllustrative sample — not a real personal memory.',position:'25% 65%'},{id:'demo-3',title:'Little everyday moments',category:'Pet',date:'2024-04-21',story:'Remembering the quiet companionship of ordinary days.\n\nIllustrative sample — upload your own photos to make this space yours.',position:'60% 75%'}].map((m,i)=>({...m,sample:true,favorite:false,createdAt:3-i,kind:'image',asset:'./assets/room.jpg'}));
let memories=[],settings=readSettings(),category='All',query='',favoriteOnly=false,pageURLs=[],garden=null,pendingFiles=[],toastTimer,audioContext,ambientNodes=[],route='',renderCounter=0;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function persistSettings(){try{writeSettings(settings);}catch{toast('Preferences could not be saved in this browser.');}}
function photo(m){if(m.blob){if(!m.blob.type.startsWith('image/'))return '';const u=URL.createObjectURL(m.blob);pageURLs.push(u);return u;}return m.asset||'';}
function releaseURLs(){pageURLs.forEach(u=>URL.revokeObjectURL(u));pageURLs=[];}
const visibleItems=()=>memories.length?memories:demos;
function newMemoryId(){return globalThis.crypto?.randomUUID?.()||'memory-'+Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');}
function intro(kicker,title,copy){return `<div class="intro"><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${copy}</p></div>`;}
function nav(){const links=[['memories','Memories'],['home','Home'],['upload','Create'],['experience','VR space'],['settings','More']];$('.dock').innerHTML=links.map(([p,label])=>`<a href="#${p}" class="${route===p?'active':''}" ${route===p?'aria-current="page"':''}>${icon(p)}${label}</a>`).join('');$('#profile-button').textContent=settings.name==='Your space'?'Y':settings.name[0]?.toUpperCase()||'Y';}
function home(){app.innerHTML=`<section class="hero"><div><span class="eyebrow">A PLACE FOR WHAT STAYS</span><h1>Some moments<br>live on.<br><em>Keep them close.</em></h1><p>A familiar place. A voice you know by heart.<br>Bring your memories together, and return to them in a space that feels like home.</p><div class="hero-actions"><a class="primary" href="#upload">Create a memory <span>↗</span></a><a class="secondary" href="#experience">Explore VR ${icon('experience')}</a></div><div class="hero-footnote">◌ &nbsp; At your pace. In your own way.</div></div><div class="memory-composition" aria-label="Illustrative memories"><div class="floating-card back"><img src="./assets/room.jpg" style="object-position:20% 50%" alt="A familiar sunlit chair"><small>A place that feels like you.</small></div><div class="floating-card"><img src="./assets/room.jpg" style="object-position:90% 40%" alt="Golden light across a peaceful lake"><small>The light we remember.</small></div><div class="floating-card front"><img src="./assets/room.jpg" style="object-position:70% 80%" alt="Lavender and warm afternoon light"><small>Little things. Lasting feelings.</small></div><div class="memory-tag">✦ &nbsp; More than a photograph.<span>&nbsp;&nbsp;&nbsp;&nbsp; A moment you can return to.</span></div></div></section><div class="section-head"><div><h2>Your journey, gently unfolding</h2><p>There is no right place to start. Just a moment that matters.</p></div><a href="#memories" class="text-button">View memories ↗</a></div><section class="journey-grid"><a href="#upload" class="journey"><span class="icon-tile">${icon('upload')}</span><div><h3>Gather a memory</h3><p>Photos, voices and the stories behind them.</p></div><span class="arrow">↗</span></a><a href="#memories" class="journey"><span class="icon-tile">${icon('memories')}</span><div><h3>Keep a connection</h3><p>A little collection of what means the most.</p></div><span class="arrow">↗</span></a><a href="#experience" class="journey"><span class="icon-tile">${icon('experience')}</span><div><h3>Step into a moment</h3><p>A quiet space to pause and remember.</p></div><span class="arrow">↗</span></a></section><p class="footline">MADE FOR MEMORIES. HELD WITH CARE.</p>`;}
function cards(items){return items.map(m=>{const url=photo(m);return `<article class="memory-card"><button class="card-cover" data-open="${esc(m.id)}" aria-label="Open ${esc(m.title)}">${url?`<img src="${url}" alt="${esc(m.title)}" style="object-position:${m.position||'50% 50%'}">`:`<span class="media-icon">${m.kind==='audio'?'♫':m.kind==='video'?'▷':'“'}</span>`}<span class="card-badge">${esc(m.category)}${m.sample?' · Sample':''}</span></button><button class="favorite ${m.favorite?'on':''}" data-favorite="${esc(m.id)}" aria-label="${m.favorite?'Unfavorite':'Favorite'} ${esc(m.title)}" aria-pressed="${!!m.favorite}">${m.favorite?'♥':'♡'}</button><div class="card-body"><h3>${esc(m.title)}</h3><div class="card-meta"><span>${esc(m.date)}</span><span>${m.kind==='text'?'Story':m.kind==='image'?'Photograph':m.kind==='audio'?'Voice note':'Video'} ↗</span></div></div></article>`;}).join('')||'<div class="empty">No memories here yet.<br><br><a href="#upload" class="primary">Create a memory ↗</a></div>';}
function updateGallery(){releaseURLs();const filtered=filterMemories(visibleItems(),{category,query,favorites:favoriteOnly});$('#gallery').innerHTML=cards(filtered);$('#result-count').textContent=`${filtered.length} ${filtered.length===1?'memory':'memories'}${!memories.length?' · illustrative collection':''}`;bindCards();}
function memoryPage(){app.innerHTML=intro('YOUR MEMORY ARCHIVE','A little closer, always.','Revisit the people, companions and places that are part of your story.')+`<div class="toolbar">${['All',...CATEGORIES].map(c=>`<button class="chip ${category===c?'active':''}" data-category="${c}" aria-pressed="${category===c}">${c==='All'?'All memories':c}</button>`).join('')}<button id="favorites-filter" class="chip ${favoriteOnly?'active':''}" aria-pressed="${favoriteOnly}">♡ Favorites</button><label class="search"><span class="sr-only" hidden>Search memories</span><input aria-label="Search memories" id="search" type="search" placeholder="Search a name, moment…" value="${esc(query)}"></label></div><div class="section-head"><p id="result-count" aria-live="polite"></p><a href="#upload" class="text-button">+ New memory</a></div><section class="gallery" id="gallery" aria-label="Memories"></section>`;updateGallery();document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render();});$('#favorites-filter').onclick=()=>{favoriteOnly=!favoriteOnly;render();};$('#search').oninput=e=>{query=e.target.value;releaseURLs();updateGallery();};}
function bindCards(){document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDetail(b.dataset.open));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=async()=>{const m=visibleItems().find(m=>m.id===b.dataset.favorite);const next={...m,favorite:!m.favorite};try{if(m.sample)Object.assign(m,next);else{await putMemories([next]);memories=await allMemories();}updateGallery();}catch{toast('Could not save this favorite.');}});}
function upload(){pendingFiles=[];app.innerHTML=intro('01 / GATHER','Every memory starts somewhere.','A photograph, a voice, or just a few words. Start with what you have.')+`<form id="memory-form" class="upload-layout"><section class="panel"><label class="dropzone" id="dropzone">${icon('upload')}<h3>Bring a moment with you</h3><p>Choose files or drag them here<br>Photos · Videos · Voice notes · Up to 25 MB each</p><input class="file-input" id="files" type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,audio/mpeg,audio/mp4,audio/wav,audio/ogg,audio/webm"></label><div id="file-preview" class="file-preview"></div><p class="file-summary" id="file-summary">No file needed to save a written memory.</p><div class="form-grid"><label class="full">Give this moment a name<input id="title" name="title" required maxlength="100" placeholder="A Sunday I still remember"></label><label>Who is this memory about?<select name="category">${CATEGORIES.map(c=>`<option>${c}</option>`).join('')}</select></label><label>Date of the memory<input type="date" name="date" value="${new Date().toISOString().slice(0,10)}" required></label><label class="full">The story behind it<textarea name="story" maxlength="5000" placeholder="What would you like to remember about this moment?"></textarea></label></div><label class="checkline"><input name="consent" type="checkbox" required><span>I have permission to keep these materials and understand they are saved in this browser.</span></label><div class="save-row"><small>◉ &nbsp; Only on this device</small><button type="submit" class="primary">Save memory <span>↗</span></button></div></section><aside class="panel"><span class="eyebrow">A SMALL BEGINNING</span><h2 class="note-title" style="margin-top:18px">Make room for<br>what matters.</h2><ol class="numbered"><li>Choose something you want to keep close.</li><li>Add the little details only you know.</li><li>Revisit it in your own memory space.</li></ol><p class="gentle-note">You do not have to tell the whole story today. A few words can be enough.<br><br>Nothing is posted publicly. Clearing this browser’s data will remove your memories; you can download a backup in More.</p></aside></form>`;
 const selectFiles=files=>{try{validateFiles(files);pendingFiles=Array.from(files);releaseURLs();$('#file-preview').innerHTML=pendingFiles.map(f=>{if(f.type.startsWith('image/')){const u=URL.createObjectURL(f);pageURLs.push(u);return `<img src="${u}" alt="Selected photograph">`;}return `<span class="chip">${esc(f.name)}</span>`;}).join('');$('#file-summary').textContent=pendingFiles.length?`${pendingFiles.length} file(s) selected · Each becomes a memory with the details below.`:'No file needed to save a written memory.';}catch(e){toast(e.message);$('#files').value='';pendingFiles=[];$('#file-preview').innerHTML='';$('#file-summary').textContent='No files selected.';}};
 $('#files').onchange=e=>selectFiles(e.target.files);const drop=$('#dropzone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('over');};drop.ondragleave=()=>drop.classList.remove('over');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('over');selectFiles(e.dataTransfer.files);};$('#memory-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));const clean=cleanMemory(data);const files=pendingFiles.length?pendingFiles:[null];await putMemories(files.map((blob,i)=>({...clean,id:newMemoryId(),title:files.length>1?`${clean.title.slice(0,90)} · ${i+1}`:clean.title,createdAt:Date.now()+i,kind:blob?blob.type.split('/')[0]:'text',blob,favorite:false})));memories=await allMemories();category='All';query='';favoriteOnly=false;location.hash='memories';toast('Your memory has a place to stay.');}catch(err){toast(err.message||'Could not save. Your browser storage may be full.');btn.disabled=false;}};}
function experience(){app.innerHTML=intro('02 / RETURN','A space to remember.','Choose an atmosphere, take a breath, and step into your collection.')+`<section class="scene-grid">${[['room','The familiar room','Warm light. A feeling of home.'],['lake','By the water','A little stillness, a little space.'],['dusk','The quiet hour','Soft colors as the day slows down.']].map(([key,title,copy])=>`<button class="scene ${settings.scene===key?'active':''}" data-scene="${key}" aria-pressed="${settings.scene===key}"><div class="scene-art ${key}"><img src="./assets/room.jpg" alt="${title}"></div><h3>${title}</h3><p>${copy}</p></button>`).join('')}</section><div class="experience-footer"><p>A seated, stationary 3D photo gallery. Explore on your screen, or enter VR with a compatible headset. These are illustrative atmospheres; photographs are not automatically reconstructed into 3D places.</p><button id="start-experience" class="primary">Step into your memories ${icon('experience')}</button></div><p class="footline">YOU CAN LEAVE AT ANY TIME. THERE IS NO NEED TO RUSH.</p>`;document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{settings.scene=b.dataset.scene;persistSettings();render();});$('#start-experience').onclick=()=>startGarden();}
function setSound(on){if(on){try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();if(!ambientNodes.length){for(const hz of [130.81,196,261.63]){const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=hz;gain.gain.value=.008;osc.connect(gain);gain.connect(audioContext.destination);osc.start();ambientNodes.push(osc);}}}catch{toast('Sound is not supported by this browser.');}}else{ambientNodes.forEach(n=>n.stop());ambientNodes=[];}}
async function startGarden(single){$('#immersive').hidden=false;document.body.style.overflow='hidden';document.querySelectorAll('.topbar,main,.dock').forEach(e=>e.inert=true);const list=single?[single]:visibleItems().slice(0,12);const opts={scene:settings.scene,onChange:m=>$('#vr-title').textContent=m.title};try{garden=new MemoryGarden($('#vr-canvas'),list,opts);$('#vr-help').textContent='Drag to look around · Use ← → to move between memories';$('#enter-xr').textContent='Enter with VR headset';$('#enter-xr').disabled=false;}catch(e){garden=new FallbackGarden($('#vr-canvas'),list,opts);$('#vr-help').textContent='Screen-only view · Swipe or use ← → to revisit memories';$('#enter-xr').textContent='VR needs a WebGL-compatible browser';$('#enter-xr').disabled=true;toast('WebGL is unavailable. Showing the screen-only gallery.');}if(settings.sound)setSound(true);$('#exit-vr').focus();}
async function exitGarden(){if(garden){await garden.dispose();garden=null;}setSound(false);$('#immersive').hidden=true;document.body.style.overflow='';document.querySelectorAll('.topbar,main,.dock').forEach(e=>e.inert=false);$('#start-experience')?.focus();}
$('#exit-vr').onclick=exitGarden;$('#vr-prev').onclick=()=>garden?.focus(garden.index-1);$('#vr-next').onclick=()=>garden?.focus(garden.index+1);$('#enter-xr').onclick=async()=>{try{await garden?.enterXR();}catch(e){toast(e.message);}};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#immersive').hidden)exitGarden();});
function settingsPage(){app.innerHTML=intro('YOUR SPACE, YOUR WAY','A little more comfort.','Make this space feel right for you.')+`<div class="settings-grid"><section class="panel"><h2 class="note-title">Experience</h2><div class="setting"><div><h3>Gentle ambient sound</h3><p>A soft tone during your memory experience.</p></div><input class="toggle" id="sound" type="checkbox" aria-label="Gentle ambient sound" ${settings.sound?'checked':''}></div><div class="setting"><div><h3>Interface transitions</h3><p>Turn off for a quieter visual experience.</p></div><input class="toggle" id="motion" type="checkbox" aria-label="Interface transitions" ${settings.motion?'checked':''}></div><div class="setting"><div><h3>Personal profile</h3><p>Your name and your collection.</p></div><a href="#profile" class="text-button">Edit ↗</a></div></section><section class="panel"><h2 class="note-title">Care & privacy</h2><div class="setting"><div><h3>Download a backup</h3><p>Includes your stories and original media files.<br>Keep this file somewhere private.</p></div><button id="export" class="text-button">Export ↓</button></div><div class="setting"><div><h3>Restore a backup</h3><p>Merge a Remember backup into this browser.</p></div><label class="text-button">Import ↑<input type="file" id="import" accept="application/json,.json" hidden></label></div><p class="gentle-note">Your collection stays in this browser. There is no account, cloud sync or public sharing in this prototype.<br><br>A memory can feel different on different days. Pause whenever you need to. Remember is a creative reflection space, not a clinical service.</p></section></div>`;$('#sound').onchange=e=>{settings.sound=e.target.checked;persistSettings();};$('#motion').onchange=e=>{settings.motion=e.target.checked;persistSettings();applyMotion();};$('#export').onclick=exportBackup;$('#import').onchange=importBackup;}
function applyMotion(){let style=$('#motion-style');if(!style){style=document.createElement('style');style.id='motion-style';document.head.append(style);}style.textContent=settings.motion?'':'*{transition:none!important;animation:none!important}';}
function profile(){app.innerHTML=intro('A PERSONAL COLLECTION','Your story, held close.','A place for the details that make these memories yours.')+`<section class="panel"><div class="profile-head"><span class="avatar">${esc(settings.name[0]?.toUpperCase()||'Y')}</span><div><h2 class="note-title" style="margin:0 0 8px">${esc(settings.name)}</h2><span class="eyebrow">PRIVATE MEMORY KEEPER</span></div></div><div class="stats"><div><strong>${memories.length}</strong><span>Memories kept</span></div><div><strong>${memories.filter(m=>m.favorite).length}</strong><span>Close to heart</span></div><div><strong>${new Set(memories.map(m=>m.category)).size}</strong><span>Connections</span></div></div><form id="profile-form"><label>Your display name<input name="name" required maxlength="40" value="${esc(settings.name)}"></label><button class="primary" style="margin-top:20px">Save profile ↗</button><a class="text-button" href="#memories">My memories →</a></form></section>`;$('#profile-form').onsubmit=e=>{e.preventDefault();settings.name=new FormData(e.target).get('name').trim()||'Your space';persistSettings();render();toast('Your profile is saved.');};}
async function openDetail(id){const m=visibleItems().find(m=>m.id===id);if(!m)return;let media='';let mediaURL;if(m.blob){mediaURL=URL.createObjectURL(m.blob);if(m.kind==='image')media=`<img src="${mediaURL}" alt="${esc(m.title)}">`;if(m.kind==='video')media=`<video src="${mediaURL}" controls playsinline></video>`;if(m.kind==='audio')media=`<audio src="${mediaURL}" controls></audio>`;}else if(m.asset)media=`<img src="${m.asset}" alt="Illustrative sunlit room">`;dialog.innerHTML=`<button class="dialog-close" aria-label="Close memory">✕</button><span class="eyebrow">${esc(m.category)} / ${esc(m.date)}${m.sample?' / SAMPLE':''}</span><h2 class="note-title" style="margin-top:20px">${esc(m.title)}</h2><div class="detail-media">${media}</div><p class="detail-story">${esc(m.story)||'A moment worth keeping.'}</p><div class="ritual" id="ritual-copy">Take a moment. There is nothing you need to do.</div><div class="detail-actions"><button id="revisit" class="primary">Revisit in VR ↗</button><button id="candle" class="secondary">✦ Light a remembrance</button>${m.sample?'':'<button id="delete-memory" class="text-button danger">Delete</button>'}</div>`;dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.onclose=()=>{dialog.querySelectorAll('audio,video').forEach(e=>e.pause());if(mediaURL)URL.revokeObjectURL(mediaURL);};$('#revisit').onclick=()=>{dialog.close();startGarden(m);};$('#candle').onclick=()=>{$('#ritual-copy').textContent='✦ A small light for this memory. Stay for as long as you like.';$('#candle').disabled=true;};if(!m.sample)$('#delete-memory').onclick=async()=>{if(!confirm('Delete this memory from this browser? This cannot be undone unless you have a backup.'))return;try{await removeMemory(m.id);memories=await allMemories();dialog.close();render();toast('Memory deleted.');}catch{toast('Could not delete this memory.');}};dialog.showModal();}
function blobBase64(blob){return new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(f.result);f.onerror=reject;f.readAsDataURL(blob);});}
async function exportBackup(){const b=$('#export');b.disabled=true;try{const list=[];for(const m of memories){const {blob,...rest}=m;list.push({...rest,media:blob?await blobBase64(blob):null});}const file=new Blob([JSON.stringify({format:'remember-v1',exportedAt:new Date().toISOString(),settings,memories:list})],{type:'application/json'});const u=URL.createObjectURL(file);const a=document.createElement('a');a.href=u;a.download=`remember-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);toast('Backup downloaded. Keep it somewhere private.');}catch{toast('Could not export this collection.');}finally{b.disabled=false;}}
async function importBackup(e){const f=e.target.files[0];if(!f)return;try{if(f.size>400*1024*1024)throw Error('This backup is too large (400 MB maximum).');const data=JSON.parse(await f.text());if(data.format!=='remember-v1'||!Array.isArray(data.memories)||data.memories.length>1000)throw Error('Choose a valid Remember backup.');const list=[];for(const m of data.memories){const clean=cleanMemory(m);if(typeof m.id!=='string'||m.id.length>100||m.id.startsWith('demo-'))throw Error('Invalid memory ID.');let blob=null;if(m.media){if(typeof m.media!=='string'||!/^data:(image\/(jpeg|png|webp|gif)|video\/(mp4|webm)|audio\/(mpeg|mp4|wav|x-wav|ogg|webm));base64,/.test(m.media))throw Error('Unsupported media in backup.');const [header,bytes]=m.media.split(',');if(bytes.length>36*1024*1024)throw Error('A media file exceeds the size limit.');const raw=atob(bytes);blob=new Blob([Uint8Array.from(raw,c=>c.charCodeAt(0))],{type:header.slice(5,-7)});validateFiles([blob]);}list.push({...clean,id:m.id,createdAt:Number.isFinite(m.createdAt)?m.createdAt:Date.now(),favorite:!!m.favorite,kind:blob?blob.type.split('/')[0]:'text',blob});}if(!confirm(`Restore ${list.length} memories? Matching IDs will be replaced; other memories will stay.`))return;await putMemories(list);memories=await allMemories();toast(`${list.length} memories restored.`);}catch(err){toast(err.message||'This backup could not be restored.');}finally{e.target.value='';}}
function render(){releaseURLs();renderCounter++;const requested=location.hash.slice(1).split('?')[0]||'home';route=['home','memories','upload','experience','profile','settings'].includes(requested)?requested:'home';({home,memories:memoryPage,upload,experience,profile,settings:settingsPage}[route])();nav();applyMotion();}
window.addEventListener('hashchange',()=>{if(!$('#immersive').hidden)exitGarden();dialog.close();render();window.scrollTo(0,0);app.focus({preventScroll:true});});$('#profile-button').onclick=()=>location.hash='profile';
try{memories=await allMemories();}catch(err){toast(err.message);}render();
